function storeRead(key){try{const data=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(data)?data:[]}catch{return []}}
function storeWrite(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{toast('Browser storage is unavailable. Your changes could not be saved.');return false}}
function getTickets(){return storeRead(KEY_TICKETS)}
function getAppointments(){return storeRead(KEY_APPOINTMENTS)}
function makeId(prefix){const digits=new Date().toISOString().slice(2,10).replaceAll('-','');const random=Math.random().toString(36).slice(2,6).toUpperCase();return `${prefix}-${digits}-${random}`}
function niceDate(raw){if(!raw)return '—';const d=new Date(raw.includes('T')?raw:raw+'T12:00:00');return Number.isNaN(d.getTime())?raw:d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}
function niceTime(raw){const [h,m]=raw.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500)}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').hidden=false;document.body.style.overflow='hidden';$('.modal-close').focus()}
function closeModal(){$('#modal').hidden=true;document.body.style.overflow=''}
function nav(page){const valid=['home','navigator','tickets','workspace','appointments','resources','about'];const section=valid.includes(page)?page:'home';$$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===section));$$('.main-nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===section));$('#main-nav').classList.remove('open');$('#nav-toggle').setAttribute('aria-expanded','false');if(location.hash.slice(1)!==section)history.replaceState(null,'','#'+section);window.scrollTo({top:0,behavior:'instant'});if(section==='workspace')renderWorkspace();if(section==='resources')renderResources();if(section==='navigator')renderWizard();updateCounts();}
function guideCard(g){return `<button class="guide-card" data-guide="${g.id}"><div class="guide-meta"><span class="category-chip">${escapeHTML(allCategories[g.category])}</span><span>${g.min} min read</span></div><h3>${escapeHTML(g.title)}</h3><p>${escapeHTML(g.description)}</p><span class="guide-action">Read step-by-step guide ${icon('arrow')}</span></button>`}
const practiceLinks={"github":[["GitHub Skills","https://skills.github.com/"]],"vscode":[["freeCodeCamp","https://www.freecodecamp.org/learn/"]],"sql":[["W3Schools SQL","https://www.w3schools.com/sql/"]],"htmlguide":[["freeCodeCamp","https://www.freecodecamp.org/learn/"],["W3Schools HTML/CSS","https://www.w3schools.com/"]],"jsguide":[["freeCodeCamp","https://www.freecodecamp.org/learn/"],["W3Schools JavaScript","https://www.w3schools.com/js/"]],"pythonguide":[["freeCodeCamp","https://www.freecodecamp.org/learn/"],["W3Schools Python","https://www.w3schools.com/python/"]],"networkguide":[["Hack The Box Academy","https://academy.hackthebox.com/"]],"linuxguide":[["Hack The Box Academy","https://academy.hackthebox.com/"]],"labguide":[["Hack The Box Academy","https://academy.hackthebox.com/"]],"debugguide":[["freeCodeCamp","https://www.freecodecamp.org/learn/"]],"nodeguide":[["W3Schools","https://www.w3schools.com/"]],"studyconcepts":[["freeCodeCamp","https://www.freecodecamp.org/learn/"],["W3Schools","https://www.w3schools.com/"]],"phishingguide":[["Hack The Box Academy","https://academy.hackthebox.com/"]]};
function showGuide(id){if(window.AccessAbleLearning){window.AccessAbleLearning.showGuide(id);return}const g=guides.find(g=>g.id===id);if(!g)return;modal(`<span class="modal-kicker">${escapeHTML(allCategories[g.category])} · ${g.min} MIN READ</span><h2 id="modal-title">${escapeHTML(g.title)}</h2><p>${escapeHTML(g.description)}</p><ol>${g.steps.map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ol><div class="note-box"><strong>Remember:</strong> ${escapeHTML(g.note)}</div>${practiceLinks[g.id]?`<div class="practice-sources"><strong>Continue practicing independently</strong><p>Optional resources from established learning platforms (not affiliated with AccessAble).</p>${practiceLinks[g.id].map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${escapeHTML(label)} ${icon('arrow')}</a>`).join('')}</div>`:''}<div class="modal-actions"><button class="btn btn-primary" data-action="from-guide" data-category="${g.category}" data-subject="${escapeHTML(g.title)}">Create related request ${icon('arrow')}</button><button class="btn btn-ghost" data-action="close-modal">Close</button></div>`)}
function renderHome(){const favorite=['portal','github','resume'];$('#home-guides').innerHTML=favorite.map(id=>guideCard(guides.find(g=>g.id===id))).join('')}
let filter='all';
function renderResources(){const query=$('#resource-query').value.toLowerCase().trim();const labels={all:'All guides',technical:'Technical',academic:'Academic',career:'Career',accessibility:'Accessibility'};$('#resource-filters').innerHTML=Object.entries(labels).map(([key,value])=>`<button class="filter ${filter===key?'active':''}" data-filter="${key}">${value}</button>`).join('');const found=guides.filter(g=>(filter==='all'||g.category===filter)&&[g.title,g.description,g.tag,g.category,...g.steps].join(' ').toLowerCase().includes(query));$('#resources-grid').innerHTML=found.map(guideCard).join('');$('#resource-count').textContent=`${found.length} guides`;$('#resource-empty').hidden=found.length>0;}
let wizard={step:0,category:null,issue:null,impact:null,preference:null,problemDetails:'',issueSearch:''};
const issueRows=category=>issues[category]||[];
const selectedIssue=()=>issueRows(wizard.category).find(row=>row[0]===wizard.issue);
const selectedTitle=()=>wizard.issue==='other'?(wizard.problemDetails.trim().slice(0,130)||'A problem not listed'):selectedIssue()?.[1]||'Support request';
const selectedGuide=()=>{let id=selectedIssue()?.[3];if(wizard.issue==='other'){const matched=issueRows(wizard.category).map(row=>({row,score:searchScore(wizard.problemDetails,[row[1],row[2],row[4]].join(' '))})).sort((a,b)=>b.score-a.score)[0];id=matched?.score>=6?matched.row[3]:({technical:'software',academic:'studyconcepts',career:'careerguide',accessibility:'meeting'}[wizard.category]);}return guides.find(g=>g.id===id)||guides.find(g=>g.category===wizard.category)||guides[0];};
const guideRelations={pythonguide:['debugguide','vscode'],jsguide:['debugguide','htmlguide'],htmlguide:['jsguide','github'],sql:['studyconcepts','vscode'],wifi:['dnsguide','networkguide'],portal:['mfaguide','browserguide'],software:['slowguide','devicecheck'],nodeguide:['debugguide','vscode'],github:['gitaccess','portfolio'],vscode:['debugguide','github'],interview:['resume','portfolio'],resume:['portfolio','linkedinguide'],labguide:['networkguide','linuxguide'],browserguide:['dnsguide','portal'],mfaguide:['portal'],networkguide:['wifi','dnsguide'],careerguide:['certs','portfolio'],focus:['paceguide','time'],captions:['formatguide','visualguide']};
function wizardOptions(options,selected,group){return `<div class="option-list">${options.map(([key,title,help])=>`<button type="button" class="option ${key===selected?'selected':''}" data-wizard-group="${group}" data-wizard-value="${key}" aria-pressed="${key===selected}"><span class="option-radio"></span><span><b>${escapeHTML(title)}</b><small>${escapeHTML(help)}</small></span></button>`).join('')}</div>`}
function issueMatches(row,q){if(!q.trim())return true;const hay=[row[1],row[2],row[4],(guides.find(g=>g.id===row[3])||{}).title].join(' ').toLowerCase();return q.toLowerCase().trim().split(/\s+/).every(term=>hay.includes(term));}
function renderIssueOptions(){const pane=$('#issue-options');if(!pane)return;const rows=issueRows(wizard.category).filter(row=>issueMatches(row,wizard.issueSearch));pane.innerHTML=rows.length?wizardOptions(rows.map(r=>r.slice(0,3)),wizard.issue,'issue'):'<p class="issue-empty">No exact topic found. Choose “My issue is not listed” and describe what is happening.</p>';
 const other=$('#issue-custom');if(other)other.hidden=wizard.issue!=='other';updateWizardContinue();}
function updateWizardContinue(){const s=wizard.step;$('#wizard-next').disabled=(s===0&&!wizard.category)||(s===1&&(!wizard.issue||(wizard.issue==='other'&&wizard.problemDetails.trim().length<8)))||(s===2&&!wizard.impact)||(s===3&&!wizard.preference);}
function renderWizard(){const titles=['What kind of help do you need?','What exactly is happening?','How much is this affecting you?','How would you like to get started?'];const s=wizard.step;$('#wizard-heading').textContent=s===4?'Here is your personalized action plan':titles[s];$('#wizard-counter').textContent=s===4?'YOUR ACTION PLAN':`STEP ${s+1} OF 4`;$('#wizard-progress').style.width=`${(s===4?4:s+1)*25}%`;$('#wizard-back').textContent=s===4?'Start over':'Back';$('#wizard-back').disabled=s===0;$('#wizard-next').style.display=s===4?'none':'';let contents='';
 if(s===0){contents='<p class="wizard-question">Start with the area closest to your situation. You can also search above.</p>'+wizardOptions([['technical','Technical problems','Accounts, devices, software, internet'],['academic','Coursework & learning','Code, assignments, GitHub, IT labs'],['career','Career & professional growth','Resume, interviews, IT career direction'],['accessibility','Accessibility & wellbeing','Inclusive tools and study support']],wizard.category,'category')}
 else if(s===1){contents=`<p class="wizard-question">Choose a topic or describe something different.</p><div class="issue-search-wrap">${icon('search')}<label for="issue-search" class="sr-only">Filter topics</label><input type="search" id="issue-search" placeholder="Find a topic: Python, VPN, GitHub..." value="${escapeHTML(wizard.issueSearch)}"><span>${issueRows(wizard.category).length} topics</span></div><div class="issue-topic-list" id="issue-options"></div><button type="button" class="other-issue ${wizard.issue==='other'?'selected':''}" data-wizard-group="issue" data-wizard-value="other">${icon('edit')}<span><b>My issue is not listed</b><small>Describe it in your own words</small></span>${icon('arrow')}</button><div class="issue-custom" id="issue-custom" ${wizard.issue==='other'?'':'hidden'}><label for="issue-description">Tell us what is happening <span class="hint">(at least 8 characters)</span></label><textarea id="issue-description" rows="3" maxlength="600" placeholder="For example: I get a permissions error when I try to push to GitHub...">${escapeHTML(wizard.problemDetails)}</textarea><p>Don't include passwords, API keys, or private personal information.</p></div>`;}
 else if(s===2){contents='<p class="wizard-question">How urgent is the problem for you?</p>'+wizardOptions(impacts,wizard.impact,'impact');}
 else if(s===3){contents='<p class="wizard-question">What would you prefer next?</p>'+wizardOptions(preferences,wizard.preference,'preference');}
 else {const g=selectedGuide();const issue=selectedTitle();const related=(guideRelations[g.id]||[]).map(id=>guides.find(x=>x.id===id)).filter(Boolean).slice(0,2);const recommendations=[g,...related];const urgency=wizard.impact==='blocked'?'High priority — you are currently blocked':wizard.impact==='limited'?'Normal priority — work can continue':'Planning priority — you are preparing ahead';contents=`<div class="navigator-result expanded-result"><span class="category-chip">PERSONALIZED SUPPORT PATH</span><h3>${escapeHTML(issue)}</h3><p>${escapeHTML(allCategories[wizard.category])} · ${urgency}</p><div class="result-plan"><h4>${icon('check')} Start with these steps</h4><ol>${g.steps.slice(0,4).map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ol><p class="result-guide-note">${escapeHTML(g.note)}</p></div><div class="related-guides"><h4>Recommended learning guides</h4>${recommendations.map((r,i)=>`<button type="button" data-guide="${r.id}"><span>${i===0?(wizard.issue==='other'?'STARTING POINT':'BEST MATCH'):'ALSO USEFUL'}</span><b>${escapeHTML(r.title)}</b>${icon('arrow')}</button>`).join('')}</div>${practiceLinks[g.id]?`<div class="result-practice"><h4>Practice and learn further</h4><p>Explore optional external learning resources.</p><div>${practiceLinks[g.id].map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${escapeHTML(label)} ${icon('arrow')}</a>`).join('')}</div></div>`:''}<div class="guided-next-steps"><span class="section-eyebrow">TRY, LEARN, THEN DECIDE</span><p>Work through the interactive guide and record which steps you tried. If it does not help, choose another path or ask for human support.</p><button type="button" class="btn btn-ghost" data-learn="wizard-alternatives">That didn’t solve it — show other options ${icon('arrow')}</button><div class="wizard-alternatives" id="wizard-alternatives" hidden></div></div><div class="result-actions"><button type="button" class="btn btn-primary" data-action="wizard-request">${wizard.preference==='session'?'Prepare a session request':'Prepare a support request'} ${icon('arrow')}</button><button type="button" class="btn btn-ghost" data-guide="${g.id}">Try step-by-step guide ${icon('book')}</button><button type="button" class="btn btn-ghost" data-learn="practice-from-guide" data-id="${g.id}">Practice a challenge ${icon('arrow')}</button></div></div><p class="wizard-help result-disclaimer">Recommendations match the selected topic using a local guide library and decision rules, not AI diagnosis. Support requests reach staff only when your Supabase connection is configured and working.</p>`;wizard.recommendedGuide=g.id;}
 $('#wizard-content').innerHTML=contents;if(s===1)renderIssueOptions();updateWizardContinue();}
function nextWizard(){if(wizard.step<4&&!$('#wizard-next').disabled){wizard.step++;renderWizard();}}
function backWizard(){if(wizard.step===4){wizard={step:0,category:null,issue:null,impact:null,preference:null,problemDetails:'',issueSearch:''}}else if(wizard.step>0){wizard.step--}renderWizard()}
function searchScore(q,text){const norm=s=>s.toLowerCase().replace(/[^a-z0-9+#]+/g,' ').trim();const query=norm(q);const hay=norm(text);if(!query||query.length<2)return 0;let score=hay.includes(query)?10:0;for(const word of query.split(/\s+/)){if(word.length<2)continue;if(hay.includes(word))score+=2;else if(word.length>3)score-=3;}return score;}
function renderNavigatorSearch(){const q=$('#navigator-search').value.trim();const region=$('#navigator-search-results');if(q.length<2){region.innerHTML='';region.hidden=true;return;}let results=[];for(const [cat,rows] of Object.entries(issues))for(const row of rows){const guide=guides.find(g=>g.id===row[3]);const score=searchScore(q,[row[1],row[2],row[4],guide?.title,guide?.tag].join(' '));if(score>0)results.push({cat,row,score});}results.sort((a,b)=>b.score-a.score);results=results.slice(0,6);region.hidden=false;region.innerHTML=results.length?`<div class="search-result-title">${results.length} helpful starting points</div>${results.map(({cat,row})=>`<button type="button" class="nav-search-result" data-action="search-topic" data-category="${cat}" data-issue="${row[0]}"><span class="category-chip">${escapeHTML(allCategories[cat])}</span><b>${escapeHTML(row[1])}</b><small>${escapeHTML(row[2])}</small>${icon('arrow')}</button>`).join('')}`:`<div class="nav-search-empty"><b>No exact match found.</b><p>That's okay. Choose a support category and use “My issue is not listed” to describe your problem.</p><button type="button" class="btn btn-primary btn-small" data-action="search-custom">Describe my problem ${icon('arrow')}</button></div>`;}
function prefillTicket(cat,subject='',description='',priority='Normal'){nav('tickets');const form=$('#ticket-form');form.elements.category.value=cat||'';form.elements.subject.value=subject;form.elements.description.value=description;form.elements.priority.value=priority}
async function submitTicket(e){e.preventDefault();const form=e.currentTarget;const data=new FormData(form);const item={id:makeId('AA'),name:String(data.get('name')||'').trim(),category:String(data.get('category')||''),subject:String(data.get('subject')||'').trim(),description:String(data.get('description')||'').trim(),priority:String(data.get('priority')||'Normal'),preference:String(data.get('preference')||'Guided resources'),status:'Pending',createdAt:new Date().toISOString(),history:[{at:new Date().toISOString(),title:'Request saved on this device',message:'Awaiting further action in the project simulation.'}]};if(!item.name||!allCategories[item.category]||!item.subject||item.description.length<12||!$('#storage-ack').checked){toast('Please complete the required fields.');return}if(window.ACCESSABLE_HAS_SUPABASE&&!window.AccessAbleCloud?.enabled){toast('Cloud is not connected. Please check Supabase setup.');return}
const online=!!window.AccessAbleCloud?.enabled;
if(online){item.history[0].title='Support request submitted';item.history[0].message='Awaiting review by an authorized staff member.';try{await window.AccessAbleCloud.createTicket(item)}catch(error){console.error(error);toast('Could not send request. Check your connection and permissions.');return}}
const items=getTickets();items.unshift(item);if(!storeWrite(KEY_TICKETS,items))return;if(online)window.dispatchEvent(new Event('accessable-cloud-refresh'));form.reset();updateCounts();
modal(`<span class="modal-kicker">YOUR REQUEST WAS SAVED</span><h2 id="modal-title">${online?'Support request received ✓':'Support request saved ✓'}</h2><p>${online?'Your request was saved to the protected support database and is waiting for staff review.':'Your request is saved in this browser only. No advisor was notified.'}</p><div class="note-box"><strong>Reference:</strong> ${escapeHTML(item.id)}<br><strong>Status:</strong> Pending<br><strong>Topic:</strong> ${escapeHTML(item.subject)}</div><div class="modal-actions"><button class="btn btn-primary" data-action="go-workspace">View my workspace ${icon('arrow')}</button><button class="btn btn-ghost" data-action="copy-ref" data-id="${escapeHTML(item.id)}">Copy reference</button></div>`)}
async function submitAppointment(e){e.preventDefault();const form=e.currentTarget;const data=new FormData(form);const date=String(data.get('date')||'');const dt=new Date(date+'T00:00:00');const today=new Date();today.setHours(0,0,0,0);if(Number.isNaN(dt.getTime())||dt<today){toast('Choose today or a future date.');return}if(!$('#appointment-ack').checked){toast('Please confirm your appointment request preferences.');return}const item={id:makeId('APT'),name:String(data.get('name')||'').trim(),category:String(data.get('category')||'technical'),date,time:String(data.get('time')||'09:00'),agenda:String(data.get('agenda')||'').trim(),preferences:data.getAll('preferences').map(String),status:'Requested locally',createdAt:new Date().toISOString()};if(!item.name||item.agenda.length<10)return;if(window.ACCESSABLE_HAS_SUPABASE&&!window.AccessAbleCloud?.enabled){toast('Cloud is not connected. Check Supabase setup.');return}
const online=!!window.AccessAbleCloud?.enabled;
if(online){item.status='Requested';try{await window.AccessAbleCloud.createAppointment(item)}catch(error){console.error(error);toast('Could not send session request. Try again.');return}}
const items=getAppointments();items.unshift(item);if(!storeWrite(KEY_APPOINTMENTS,items))return;if(online)window.dispatchEvent(new Event('accessable-cloud-refresh'));form.reset();setMinDate();updateCounts();modal(`<span class="modal-kicker">YOUR PREFERRED SESSION IS SAVED</span><h2 id="modal-title">${online?'Appointment request received ✓':'Appointment preference saved ✓'}</h2><p>${online?'Your request was sent to the support database. This is a preferred time, not a confirmed booking.':'You saved a preferred time locally. No advisor has been notified.'}</p><div class="note-box"><strong>Reference:</strong> ${escapeHTML(item.id)}<br><strong>Type:</strong> ${escapeHTML(allCategories[item.category])}<br><strong>Preferred time:</strong> ${niceDate(item.date)} at ${niceTime(item.time)} Pacific Time<br><strong>Status:</strong> ${escapeHTML(item.status)}</div><div class="modal-actions"><button class="btn btn-primary" data-action="go-workspace" data-tab="appointments">Open my appointments ${icon('arrow')}</button><button class="btn btn-ghost" data-action="calendar" data-id="${escapeHTML(item.id)}">Download tentative calendar reminder ${icon('download')}</button></div>`)}
function setMinDate(){const date=$('#appointment-date');const local=new Date();const y=local.getFullYear(),m=String(local.getMonth()+1).padStart(2,'0'),d=String(local.getDate()).padStart(2,'0');date.min=`${y}-${m}-${d}`}
function updateCounts(){const t=getTickets();const a=getAppointments();const count=t.length+a.length;$('#nav-count').hidden=count===0;$('#nav-count').textContent=count}
let workTab='tickets';
function statCard(iconName,value,label){return `<div class="stat-card"><span>${icon(iconName)}</span><strong>${value}</strong><small>${escapeHTML(label)}</small></div>`}
function renderWorkspace(){const tickets=getTickets();const appts=getAppointments();$('#workspace-stats').innerHTML=statCard('ticket',tickets.length,'Saved requests')+statCard('clock',tickets.filter(t=>['Pending','In progress'].includes(t.status)).length,'Open requests')+statCard('check',tickets.filter(t=>t.status==='Resolved').length,'Resolved in lab')+statCard('calendar',appts.filter(a=>a.status!=='Cancelled').length,'Session preferences');$$('[data-work-tab]').forEach(b=>b.classList.toggle('active',b.dataset.workTab===workTab));if(workTab==='tickets'){$('#workspace-content').innerHTML=tickets.length?tickets.map(t=>`<div class="request-card"><div><div class="request-top"><span class="ref">${escapeHTML(t.id)}</span><span class="status-pill ${statusClass(t.status)}">${escapeHTML(t.status)}</span><span class="status-pill">${escapeHTML(t.priority)}</span></div><h3>${escapeHTML(t.subject)}</h3><p>${escapeHTML(allCategories[t.category]||'Support')} · Saved ${niceDate(t.createdAt)}</p></div><div class="actions"><button data-action="ticket-detail" data-id="${escapeHTML(t.id)}">View timeline ${icon('arrow')}</button></div></div>`).join(''):emptyCard('ticket','No requests saved yet','Create your first support request and it will appear in this workspace.','tickets','Create request')}
else{$('#workspace-content').innerHTML=appts.length?appts.map(a=>`<div class="request-card"><div><div class="request-top"><span class="ref">${escapeHTML(a.id)}</span><span class="status-pill ${statusClass(a.status)}">${escapeHTML(a.status)}</span></div><h3>${escapeHTML(allCategories[a.category]||'Online support session')}</h3><p>Preferred ${niceDate(a.date)} · ${niceTime(a.time)} PT</p></div><div class="actions"><button data-action="appointment-detail" data-id="${escapeHTML(a.id)}">View details ${icon('arrow')}</button></div></div>`).join(''):emptyCard('calendar','No session preferences saved','Plan a preferred online support time and keep the details here.','appointments','Plan a session')}}
function statusClass(s){if(s==='Resolved')return 'resolved';if(s==='In progress')return 'progress';if(s==='Pending')return 'pending';if(s==='Cancelled')return 'cancelled';return ''}
function emptyCard(ico,title,body,target,buttonText){return `<div class="empty-state"><div class="empty-graphic">${icon(ico)}</div><h3>${title}</h3><p>${body}</p><button class="btn btn-primary" data-nav="${target}">${buttonText} ${icon('arrow')}</button></div>`}
function ticketDetail(id){const t=getTickets().find(t=>t.id===id);if(!t)return;modal(`<span class="modal-kicker">REQUEST ${escapeHTML(t.id)}</span><h2 id="modal-title">${escapeHTML(t.subject)}</h2><span class="status-pill ${statusClass(t.status)}">${escapeHTML(t.status)}</span><div class="detail-list"><div><span>Category</span><strong>${escapeHTML(allCategories[t.category]||'Support')}</strong></div><div><span>Impact</span><strong>${escapeHTML(t.priority)}</strong></div><div><span>Saved</span><strong>${niceDate(t.createdAt)}</strong></div><div><span>Preferred next step</span><strong>${escapeHTML(t.preference)}</strong></div></div><h3>Issue description</h3><p style="white-space:pre-wrap;overflow-wrap:anywhere">${escapeHTML(t.description)}</p><h3>Request timeline</h3><div class="timeline">${(t.history||[]).slice().reverse().map(h=>`<div class="timeline-entry"><strong>${escapeHTML(h.title)}</strong><small>${niceDate(h.at)}</small><p>${escapeHTML(h.message)}</p></div>`).join('')}</div>${t.status!=='Cancelled'?`<label>Add an update to this request<textarea rows="3" maxlength="450" id="ticket-update" placeholder="Describe a new troubleshooting step or outcome..."></textarea></label>`:''}<div class="modal-actions">${t.status!=='Cancelled'?`<button class="btn btn-primary" data-action="add-update" data-id="${escapeHTML(t.id)}">Save update</button><button class="btn btn-ghost" data-action="cancel-ticket" data-id="${escapeHTML(t.id)}">Cancel request</button>`:`<button class="btn btn-primary" data-action="reopen-ticket" data-id="${escapeHTML(t.id)}">Reopen request</button>`}<button class="btn btn-ghost" data-action="copy-ref" data-id="${escapeHTML(t.id)}">Copy reference</button></div><div class="note-box">${window.AccessAbleCloud?.enabled?'Student updates are saved to the support database and can be read by authorized staff.':'In this offline preview, student notes do not go to staff. Status changes are simulated only in this browser.'}</div>`)}
async function updateTicket(id,action){const items=getTickets();const t=items.find(x=>x.id===id);if(!t)return;if(action==='add-update'){const input=$('#ticket-update');const note=(input?.value||'').trim();if(note.length<3){toast('Write a brief update first.');return}t.history.push({at:new Date().toISOString(),title:'Student update saved',message:note})}else if(action==='cancel-ticket'){t.status='Cancelled';t.history.push({at:new Date().toISOString(),title:'Request cancelled locally',message:'The student cancelled this device-only request.'})}else if(action==='reopen-ticket'){t.status='Pending';t.history.push({at:new Date().toISOString(),title:'Request reopened',message:'Returned to pending in this browser.'})}if(window.ACCESSABLE_HAS_SUPABASE&&!window.AccessAbleCloud?.enabled){toast('Cloud unavailable. Update not saved.');return}
if(window.AccessAbleCloud?.enabled){try{await window.AccessAbleCloud.updateTicket(t)}catch(e){console.error(e);toast('Cloud update failed. No changes saved.');return}}
if(storeWrite(KEY_TICKETS,items)){if(window.AccessAbleCloud?.enabled)window.dispatchEvent(new Event('accessable-cloud-refresh'));renderWorkspace();ticketDetail(id);toast(window.AccessAbleCloud?.enabled?'Request updated securely.':'Request updated in this browser.')}}
function appointmentDetail(id){const a=getAppointments().find(a=>a.id===id);if(!a)return;modal(`<span class="modal-kicker">SESSION PREFERENCE ${escapeHTML(a.id)}</span><h2 id="modal-title">${escapeHTML(allCategories[a.category]||'Online support')}</h2><span class="status-pill ${statusClass(a.status)}">${escapeHTML(a.status)}</span><div class="detail-list"><div><span>Preferred date</span><strong>${niceDate(a.date)}</strong></div><div><span>Preferred time</span><strong>${niceTime(a.time)} Pacific Time</strong></div><div><span>Name</span><strong>${escapeHTML(a.name)}</strong></div><div><span>Preferences</span><strong>${escapeHTML(a.preferences.length?a.preferences.join(', '):'None noted')}</strong></div></div><h3>Session agenda</h3><p style="white-space:pre-wrap;overflow-wrap:anywhere">${escapeHTML(a.agenda)}</p><div class="note-box">This is not a real booking. The calendar file is a tentative personal reminder and does not send invitations to an advisor.</div><div class="modal-actions"><button class="btn btn-primary" data-action="calendar" data-id="${escapeHTML(a.id)}">Export tentative reminder ${icon('download')}</button>${a.status!=='Cancelled'?`<button class="btn btn-ghost" data-action="cancel-appointment" data-id="${escapeHTML(a.id)}">Cancel local request</button>`:''}<button class="btn btn-ghost" data-action="copy-ref" data-id="${escapeHTML(a.id)}">Copy reference</button></div>`)}
async function cancelAppointment(id){const items=getAppointments();const a=items.find(x=>x.id===id);if(!a)return;a.status='Cancelled';if(window.ACCESSABLE_HAS_SUPABASE&&!window.AccessAbleCloud?.enabled){toast('Cloud unavailable. Nothing changed.');return}if(window.AccessAbleCloud?.enabled){try{await window.AccessAbleCloud.updateAppointment(a)}catch(e){console.error(e);toast('Could not cancel this cloud request.');return}}if(storeWrite(KEY_APPOINTMENTS,items)){renderWorkspace();appointmentDetail(id);toast('Session preference cancelled.')}}
function calendarICS(id){const a=getAppointments().find(x=>x.id===id);if(!a)return;const start=new Date(`${a.date}T${a.time}:00`);if(Number.isNaN(start.getTime()))return;const end=new Date(start.getTime()+30*60*1000);const icsDate=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('')+'T'+[String(d.getHours()).padStart(2,'0'),String(d.getMinutes()).padStart(2,'0'),'00'].join('');const clean=s=>String(s).replace(/[\\;,\n]/g,' ').slice(0,130);const contents=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//AccessAble//Prototype//EN','BEGIN:VEVENT',`UID:${clean(a.id)}@accessable.local`,'STATUS:TENTATIVE',`DTSTART:${icsDate(start)}`,`DTEND:${icsDate(end)}`,`SUMMARY:${clean('Tentative — '+(allCategories[a.category]||'IT support session'))}`,`DESCRIPTION:${clean('Self-saved preference only. No advisor booked. Reference '+a.id)}`,'END:VEVENT','END:VCALENDAR'].join('\r\n');const blob=new Blob([contents],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='AccessAble-tentative-'+a.id+'.ics';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Tentative calendar reminder downloaded. No appointment is confirmed.')}
async function copyRef(value){try{await navigator.clipboard.writeText(value);toast('Reference copied.')}catch{toast('Copy is unavailable in this browser.')}}
function clearData(){if(!window.confirm('Delete all AccessAble requests and appointment preferences saved in this browser? This cannot be undone.'))return;localStorage.removeItem(KEY_TICKETS);localStorage.removeItem(KEY_APPOINTMENTS);closeModal();updateCounts();renderWorkspace();toast('Local AccessAble data cleared.')}
function bind(){document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.nav){nav(btn.dataset.nav);return}if(btn.dataset.categoryGo){wizard={step:0,category:btn.dataset.categoryGo,issue:null,impact:null,preference:null,problemDetails:'',issueSearch:''};nav('navigator');return}if(btn.dataset.guide){showGuide(btn.dataset.guide);return}if(btn.dataset.filter){filter=btn.dataset.filter;renderResources();return}if(btn.dataset.workTab){workTab=btn.dataset.workTab;renderWorkspace();return}if(btn.dataset.wizardGroup){const {wizardGroup, wizardValue}=btn.dataset;wizard[wizardGroup]=wizardValue;if(wizardGroup==='category'){wizard.issue=null;wizard.issueSearch='';wizard.problemDetails=''}if(wizardGroup==='issue'&&wizardValue!=='other')wizard.problemDetails='';renderWizard();return}const action=btn.dataset.action;if(!action)return;if(action==='search-topic'){wizard={step:2,category:btn.dataset.category,issue:btn.dataset.issue,impact:null,preference:null,problemDetails:'',issueSearch:''};renderWizard();$('#wizard-heading').scrollIntoView({block:'center',behavior:'smooth'});return}if(action==='search-custom'){wizard={step:0,category:null,issue:null,impact:null,preference:null,problemDetails:'',issueSearch:''};renderWizard();$('#wizard-heading').scrollIntoView({block:'center',behavior:'smooth'});return}if(action==='close-modal')closeModal();if(action==='go-workspace'){workTab=btn.dataset.tab||'tickets';closeModal();nav('workspace')}if(action==='from-guide'){const cat=btn.dataset.category,subject=btn.dataset.subject;closeModal();prefillTicket(cat,subject)}if(action==='wizard-request'){const cat=wizard.category;const chosen=(issues[cat]||[]).find(i=>i[0]===wizard.issue)||[];const impact=wizard.impact==='blocked'?'High':wizard.impact==='planning'?'Low':'Normal';const pref=wizard.preference;const info=`My situation: ${wizard.issue==='other'?wizard.problemDetails:chosen[1]||'Need support'}. Impact: ${wizard.impact}. Preferred next step: ${pref}. Suggested guide: ${selectedGuide().title}.`;if(pref==='session'){nav('appointments');const appointment=$('#appointment-form');appointment.elements.category.value=cat;appointment.elements.agenda.value=`I'd like an online session about: ${selectedTitle()}. I have reviewed the suggested troubleshooting guide. My priority is ${impact.toLowerCase()}.`;appointment.elements.agenda.focus()}else{prefillTicket(cat,selectedTitle().slice(0,115),info,impact);$('#ticket-form').elements.preference.value=pref==='ticket'?'Written follow-up':'Guided resources'}}if(action==='copy-ref')copyRef(btn.dataset.id);if(action==='ticket-detail')ticketDetail(btn.dataset.id);if(['add-update','cancel-ticket','reopen-ticket'].includes(action))updateTicket(btn.dataset.id,action);if(action==='appointment-detail')appointmentDetail(btn.dataset.id);if(action==='cancel-appointment')cancelAppointment(btn.dataset.id);if(action==='calendar')calendarICS(btn.dataset.id);if(action==='clear-data')clearData();});$('#nav-toggle').addEventListener('click',()=>{const navEl=$('#main-nav');const open=navEl.classList.toggle('open');$('#nav-toggle').setAttribute('aria-expanded',String(open))});$('#wizard-back').addEventListener('click',backWizard);$('#wizard-next').addEventListener('click',nextWizard);$('#ticket-form').addEventListener('submit',submitTicket);$('#appointment-form').addEventListener('submit',submitAppointment);$('#resource-query').addEventListener('input',renderResources);$('#navigator-search').addEventListener('input',renderNavigatorSearch);document.addEventListener('input',e=>{if(e.target.id==='issue-search'){wizard.issueSearch=e.target.value;renderIssueOptions()}if(e.target.id==='issue-description'){wizard.problemDetails=e.target.value;updateWizardContinue()}});$('#modal').addEventListener('click',e=>{if(e.target.classList.contains('modal-shade'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').hidden)closeModal()});window.addEventListener('hashchange',()=>nav(location.hash.replace('#','')))}
function init(){document.getElementById('year').textContent=new Date().getFullYear();renderHome();$('#faq-list').innerHTML=faqs.map(([q,a])=>`<details><summary>${escapeHTML(q)}</summary><p>${escapeHTML(a)}</p></details>`).join('');renderWizard();renderResources();setMinDate();bind();nav(location.hash.replace('#','')||'home')}
document.addEventListener('DOMContentLoaded',init);

window.addEventListener('accessable-cloud-ready',()=>{
 const storage=document.querySelector('label[for="storage-ack"]');if(storage)storage.textContent='I understand my request will be stored in the AccessAble support database and may be read by authorized staff. *';
 const apt=document.querySelector('label[for="appointment-ack"]');if(apt)apt.textContent='I understand this submits a preferred time, not an approved appointment. *';
 const note=document.querySelector('.workspace-footnote');if(note)note.textContent='Your requests are linked to this browser’s anonymous Supabase identity. To keep access, do not clear site data. Staff can review shared cloud requests.';
 const footerActions=document.querySelector('.footer-local-actions');if(footerActions)footerActions.hidden=true;
 const modalNote=document.querySelector('#view-workspace .workspace-footnote');if(modalNote)modalNote.textContent='Cloud requests sync when you revisit this tab. Your student identity is tied to this browser.';
 const formFooter=document.querySelector('#ticket-form .form-footer span');if(formFooter)formFooter.textContent='Saved to protected support database';
 const faq=document.querySelector('#faq-list');if(faq){const item=faq.querySelector('details:last-child'); if(item){const summary=item.querySelector('summary');const answer=item.querySelector('p');if(summary)summary.textContent='How does the staff portal work?';if(answer)answer.textContent='Authorized staff sign in with an email and password. Supabase Authentication verifies identity and PostgreSQL rules restrict access to staff accounts granted by the project owner.';}}
});
window.addEventListener('accessable-cloud-data',event=>{
 if(!window.AccessAbleCloud?.enabled)return;
 const d=event.detail;
 if(d&&Array.isArray(d.tickets)&&Array.isArray(d.appointments)){
  storeWrite(KEY_TICKETS,d.tickets);storeWrite(KEY_APPOINTMENTS,d.appointments);updateCounts();renderWorkspace();
 }
});
window.addEventListener('accessable-cloud-error',event=>{
 toast(event.detail||'Cloud sync failed. Requests cannot reach staff right now.');
});
